c/BYTE.jl]: module BYTE\r\n\r\nusing HTTP, HTTP.WebSockets, JSON, SQLite, DataFrames, Dates, UUIDs\r\n\r\ninclude(\"UI.jl\")\r\ninclude(\"Schema.jl\")\r\ninclude(\"Tools.jl\")\r\ninclude(\"Telemetry.jl\")\r\n\r\nexport init, serve, launch, process_message, install_cognitive_callback!\r\n\r\n# External bridge — set by the parent (App.jl) so BYTE's HTTP server can\r\n# delegate unknown paths to the A2A server (webhooks, welcome page, agent\r\n# card, JSON-RPC).  Keeps BYTE dependency-free; A2A owns its own routes.\r\n#\r\n# Signature:  (req::HTTP.Request) -> Union{HTTP.Response, Nothing}\r\n# Return `nothing` to let BYTE fall through to its 404.\r\nconst _EXTRA_HTTP_HANDLER = Ref{Any}(nothing)\r\n\r\n\"\"\"\r\n    register_extra_http_handler!(fn)\r\n\r\nInstall a fallback HTTP handler called for any request BYTE doesn't match\r\nitself (`/health`, `/`, WebSocket upgrades).  Return `nothing` to 404.\r\n\"\"\"\r\nfunction register_extra_http_handler!(fn)\r\n    _EXTRA_HTTP_HANDLER[] = fn\r\n    return\r\nend\r\n\r\n\"\"\"\r\n    init(db, browser_context)\r\n\r\nWire live resources (SQLite DB and Playwright browser context) into the tool layer.\r\n\"\"\"\r\nfunction init(db::SQLite.DB, browser_context, project_root::String=\"\")\r\n    init_tools(db, browser_context, project_root)\r\n    !isempty(project_root) && init_telemetry(project_root; db=db)\r\n\r\n    # Register cognitive broadcast hook — fires live to terminal panel\r\n    _COGNITIVE_HOOK[] = _broadcast_cognitive\r\n\r\n    # Register forge hook — streams every successful forge event to all UI tabs\r\n    empty!(_FORGE_HOOKS)\r\n    push!(_FORGE_HOOKS, (name, code, description) -> begin\r\n        lines = split(code, \"\\n\")\r\n        _broadcast(Dict(\"type\"=>\"forge_start\", \"name\"=>name,\r\n                        \"description\"=>description, \"total_lines\"=>length(lines)))\r\n        log_cognitive_forge(name, \"start\", \"Forging tool_$(name) ($(length(lines)) lines)\")\r\n        for (i, line) in enumerate(lines)\r\n            _broadcast(Dict(\"type\"=>\"forge_line\", \"name\"=>name,\r\n                            \"line\"=>line, \"line_num\"=>i, \"total_lines\"=>length(lines)))\r\n            sleep(0.018)   # ~55 lines/sec — fast enough to feel live, slow enough to read\r\n        end\r\n        _broadcast(Dict(\"type\"=>\"forge_done\", \"name\"=>name, \"total_lines\"=>length(lines)))\r\n        log_cognitive_forge(name, \"done\", \"Tool_$(name) forged successfully ($(length(lines)) lines)\")\r\n    end)\r\nend\r\n\r\n\"\"\"\r\n    install_cognitive_callback!(engine)\r\n\r\nWire JLEngine's cognitive_callback to the terminal broadcast system. Called from\r\nsrc/App.jl after engine construction so engine ticks flow into the terminal panel.\r\n\"\"\"\r\nfunction install_cognitive_callback!(engine)\r\n    Main.JLEngine.set_cognitive_callback!(engine, (snapshot, event_symbol) -> begin\r\n        if event_symbol === :gait_change\r\n            log_cognitive_thought(\"Gait shift: $(snapshot[\"from\"]) → $(snapshot[\"to\"])\")\r\n        elseif event_symbol === :analyze_done\r\n            log_cognitive_state(snapshot)\r\n        elseif event_symbol === :record_turn\r\n            _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"turn_recorded\",\r\n                            \"stability\"=>get(snapshot,\"stability\",0.0),\r\n                            \"reply_len\"=>get(snapshot,\"reply_len\",0)))\r\n        elseif event_symbol === :run_turn\r\n            _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"turn_complete\",\r\n                            \"stability\"=>get(snapshot,\"stability\",0.0),\r\n                            \"reply_len\"=>get(snapshot,\"reply_len\",0)))\r\n        end\r\n    end)\r\n    return\r\nend\r\n\r\n# --- Session State ---\r\nglobal _current_model = \"anthropic/claude-3.7-sonnet\"\r\nglobal _current_gear  = \"LITE_REASONING\"\r\nglobal _active_modes  = [\"SASS\", \"HUMAN\", \"BINDING\"]\r\nconst  _generation_abort = Ref(false)   # set true to break the agentic loop\r\n\r\nconst _NO_TOOL_MODELS = String[]\r\n\r\nfunction _model_supports_tools(model::AbstractString)::Bool\r\n    return true\r\nend\r\n\r\n# Confirmation flag and pending store\r\nconst REQUIRE_CONFIRM = Ref(false)  # UI can confirm tool runs, but keep opt-in until we want approval gates\r\nconst _pending_confirms = Dict{String,Dict{String,Any}}()  # id => {fn, args}\r\n\r\n# ── Connected WebSocket clients — for broadcast (forge stream, etc.) ──────────\r\nconst _WS_CLIENTS      = Dict{UInt64, Any}()   # objectid(ws) => ws\r\nconst _WS_CLIENTS_LOCK = ReentrantLock()\r\n\r\nfunction _broadcast(msg::Dict)\r\n    json_str = JSON.json(msg)\r\n    lock(_WS_CLIENTS_LOCK) do\r\n        dead = UInt64[]\r\n        for (id, ws) in _WS_CLIENTS\r\n            try\r\n                WebSockets.send(ws, json_str)\r\n            catch\r\n                push!(dead, id)\r\n            end\r\n        end\r\n        for id in dead; delete!(_WS_CLIENTS, id); end\r\n    end\r\nend\r\n\r\n# ── Cognitive broadcast — fires live cognitive events to ALL connected clients ──\r\nfunction _broadcast_cognitive(args...)\r\n    # args: (\"thought\", text)\r\n    #       (\"tool\", name, status, detail)\r\n    #       (\"state\", gait, rhythm, aperture, behavior, drift)\r\n    #       (\"forge\", name, status, detail)\r\n    #       (\"api\", model, status, detail)\r\n    if length(args) < 2\r\n        return\r\n    end\r\n    event_type = string(args[1])\r\n    if event_type == \"thought\"\r\n        text = string(args[2])\r\n        _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"thought\", \"text\"=>text))\r\n    elseif event_type == \"tool\"\r\n        name   = string(args[2])\r\n        status = string(args[3])\r\n        detail = length(args) >= 4 ? string(args[4]) : \"\"\r\n        _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"tool\",\r\n                        \"name\"=>name, \"status\"=>status, \"detail\"=>detail))\r\n    elseif event_type == \"state\"\r\n        gait    = string(args[2])\r\n        rhythm  = string(args[3])\r\n        aper    = string(args[4])\r\n        behav   = string(args[5])\r\n        drift   = string(args[6])\r\n        _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"state\",\r\n                        \"gait\"=>gait, \"rhythm\"=>rhythm,\r\n                        \"aperture\"=>aper, \"behavior\"=>behav, \"drift\"=>drift))\r\n    elseif event_type == \"forge\"\r\n        name   = string(args[2])\r\n        status = string(args[3])\r\n        detail = length(args) >= 4 ? string(args[4]) : \"\"\r\n        _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"forge\",\r\n                        \"name\"=>name, \"status\"=>status, \"detail\"=>detail))\r\n    elseif event_type == \"api\"\r\n        model  = string(args[2])\r\n        status = string(args[3])\r\n        detail = length(args) >= 4 ? string(args[4]) : \"\"\r\n        _broadcast(Dict(\"type\"=>\"cognitive\", \"event\"=>\"api\",\r\n                        \"model\"=>model, \"status\"=>status, \"detail\"=>detail))\r\n    end\r\nend\r\n\r\n# Safe WebSocket send — now logs errors instead of silently dropping them.\r\nfunction _ws_send(ws, msg::String)\r\n    try\r\n        WebSockets.send(ws, msg)\r\n    catch e\r\n        # ECANCELED / EOFError = client disconnected — totally normal, don't spam\r\n        err_str = string(e)\r\n        if !occursin(\"ECANCELED\", err_str) && !occursin(\"EOFError\", err_str) && !occursin(\"closed\", lowercase(err_str))\r\n            @warn \"WebSocket send failed\" exception=e\r\n        end\r\n    end\r\nend\r\n_ws_send(ws, d::Dict) = _ws_send(ws, JSON.json(d))\r\n\r\nfunction _project_path(root::String, relative_path::String)\r\n    normalized = replace(strip(relative_path), \"\\\\\" => \"/\")\r\n    parts = [part for part in split(normalized, \"/\") if !isempty(part) && part != \".\"]\r\n    return isempty(parts) ? root : normpath(joinpath(root, parts...))\r\nend\r\n\r\nfunction _ollama_openai_endpoint()\r\n    explicit = strip(get(ENV, \"OLLAMA_OPENAI_ENDPOINT\", \"\"))\r\n    !isempty(explicit) && return explicit\r\n    base = rstrip(strip(get(ENV, \"OLLAMA_BASE_URL\", \"http://localhost:11434\")), '/')\r\n    return \"$base/v1/chat/completions\"\r\nend\r\n\r\n# Send tool start + done messages to UI with result preview and elapsed time.\r\nfunction _send_tool_start(ws, name::String)\r\n    _ws_send(ws, Dict(\"type\"=>\"tool_start\", \"name\"=>name))\r\nend\r\nfunction _send_tool_done(ws, name::String, res::Dict, elapsed_ms::Int)\r\n    # Build a short human-readable result preview\r\n    preview = if haskey(res\n[self_src/BYTE/src/Tools.jl]: haskey(ENV, \"JULIA_CONDAPKG_BACKEND\") || (ENV[\"JULIA_CONDAPKG_BACKEND\"] = \"Null\")\r\nhaskey(ENV, \"JULIA_PYTHONCALL_EXE\") || (ENV[\"JULIA_PYTHONCALL_EXE\"] = \"python\")\r\n\r\nusing SQLite, DataFrames, Dates, JSON, HTTP, Base64\r\n\r\n# Python is optional: without it the engine runs fine, just with browser/\r\n# Python-backed tools disabled. PythonCall must NOT be loaded at include/\r\n# precompile time — that would bake a hard Python dependency into the\r\n# package cache and abort boot on machines without Python (or with Python\r\n# removed after the cache was built). Load it lazily on first use instead.\r\nconst _PYTHONCALL = Ref{Any}(nothing)\r\npython_available() = Sys.which(get(ENV, \"JULIA_PYTHONCALL_EXE\", \"python\")) !== nothing\r\nfunction _python_module()\r\n    if _PYTHONCALL[] === nothing\r\n        python_available() || error(\"Python is not installed on this machine — this tool needs Python 3 (see INSTALL.md)\")\r\n        _PYTHONCALL[] = Base.require(Base.PkgId(Base.UUID(\"6099a3de-0909-46bc-b1f4-468b9a2dfc0d\"), \"PythonCall\"))\r\n    end\r\n    return _PYTHONCALL[]\r\nend\r\npyimport(name) = _python_module().pyimport(name)\r\npyconvert(T, x) = _python_module().pyconvert(T, x)\r\n\r\n# Lazy-initialized singletons — set by BYTE.init()\r\nconst _state = Dict{Symbol, Any}(\r\n    :db => nothing,\r\n    :browser_context => nothing,\r\n)\r\n\r\n# Mutable live registry for dynamically forged tools\r\nconst DYNAMIC_SCHEMA       = Dict{String,Any}[]\r\nconst _project_root        = Ref{String}(\"\")\r\nconst _session_event_count = Ref{Int}(0)\r\n\r\n# ── Forge event hooks — registered by BYTE on init for live dashboard broadcast ──\r\n# Each entry is fn(name::String, code::String, description::String) -> nothing\r\nconst _FORGE_HOOKS = Function[]\r\n\r\n# ── Live Memory Listener ──────────────────────────────────────────────────────\r\n\r\nfunction _db_write_thought(context::String, thought::String, mood::String, gait::String, agent::String=\"SparkByte\"; type::String=\"diary\", model::String=\"\")\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    try\r\n        SQLite.execute(db,\r\n            \"INSERT INTO thoughts (timestamp, agent, context, thought, mood, gait, type, model) VALUES (?,?,?,?,?,?,?,?)\",\r\n            (string(now()), agent, first(context, 120), first(thought, 400), mood, gait, type, model))\r\n        _session_event_count[] += 1\r\n    catch e\r\n        @warn \"Thought write failed\" exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\nfunction _db_write_turn_snapshot(snapshot::Dict, agent::String, model::String,\r\n                                  session_id::String, turn_number::Int,\r\n                                  user_msg_len::Int, reply_len::Int, elapsed_ms::Int)\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    try\r\n        rhythm    = get(snapshot, \"rhythm\",        Dict())\r\n        aperture  = get(snapshot, \"aperture_state\", Dict())\r\n        behavior  = get(snapshot, \"behavior_state\", Dict())\r\n        drift     = get(snapshot, \"drift\",          Dict())\r\n        advisory  = get(snapshot, \"advisory\",       Dict())\r\n        SQLite.execute(db, \"\"\"\r\n            INSERT INTO turn_snapshots\r\n            (timestamp, session_id, turn_number, agent, model,\r\n             gait, rhythm_mode, rhythm_momentum,\r\n             aperture_mode, aperture_temp, aperture_top_p,\r\n             behavior_state, behavior_expressiveness, behavior_pacing, behavior_tone,\r\n             drift_pressure, drift_temp_delta, drift_action_level,\r\n             advisory_bias, advisory_emotional_drift, advisory_msg,\r\n             user_msg_len, reply_len, elapsed_ms)\r\n            VALUES (?,?,?,?,?, ?,?,?, ?,?,?, ?,?,?,?, ?,?,?, ?,?,?, ?,?,?)\"\"\",\r\n            (string(now()), session_id, turn_number, agent, model,\r\n             string(get(snapshot, \"gait\", \"\")),\r\n             string(get(rhythm, \"mode\", \"\")),\r\n             Float64(get(rhythm, \"momentum\", 0.0)),\r\n             string(get(aperture, \"mode\", \"\")),\r\n             Float64(get(aperture, \"temp\", 0.0)),\r\n             Float64(get(aperture, \"top_p\", 0.0)),\r\n             string(get(behavior, \"name\", \"\")),\r\n             Float64(get(behavior, \"expressiveness\", 0.0)),\r\n             string(get(behavior, \"pacing\", \"\")),\r\n             string(get(behavior, \"tone_bias\", \"\")),\r\n             Float64(get(drift, \"pressure\", 0.0)),\r\n             Float64(get(drift, \"temperature_delta\", 0.0)),\r\n             string(get(drift, \"action_level\", \"\")),\r\n             string(get(advisory, \"gating_bias\", \"\")),\r\n             string(get(advisory, \"emotional_drift\", \"\")),\r\n             string(get(advisory, \"msg\", \"\")),\r\n             user_msg_len, reply_len, elapsed_ms))\r\n        _session_event_count[] += 1\r\n    catch e\r\n        @warn \"Turn snapshot write failed\" exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\n# Store raw reasoning/thinking traces from reasoning models\r\nfunction _db_write_reasoning(context::String, reasoning::String, model::String, agent::String=\"SparkByte\")\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    isempty(strip(reasoning)) && return\r\n    try\r\n        SQLite.execute(db,\r\n            \"INSERT INTO thoughts (timestamp, agent, context, thought, mood, gait, type, model) VALUES (?,?,?,?,?,?,?,?)\",\r\n            (string(now()), agent, first(context, 120), first(reasoning, 2000), \"reasoning\", \"auto\", \"reasoning\", model))\r\n        _session_event_count[] += 1\r\n    catch e\r\n        @warn \"Reasoning write failed\" exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\nfunction _db_write_tool_usage(name::String, args_json::String, result_json::String, elapsed_ms::Int, agent::String)\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    try\r\n        SQLite.execute(db,\r\n            \"INSERT INTO tool_usage_log (timestamp, tool_name, args_json, result_json, duration_ms, agent, session_id) VALUES (?,?,?,?,?,?,?)\",\r\n            (string(now()), name, first(args_json, 500), first(result_json, 500), elapsed_ms, agent, isdefined(@__MODULE__, :_session_id) ? string(getfield(@__MODULE__, :_session_id)) : \"unknown\"))\r\n        SQLite.execute(db, \"UPDATE tools SET call_count = call_count + 1, last_used = ? WHERE name = ?\", (string(now()), name))\r\n        _session_event_count[] += 1\r\n    catch e\r\n        @warn \"Tool usage write failed\" exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\nfunction _db_write_web_cache(url::String, content::String)\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    try\r\n        existing = DBInterface.execute(db, \"SELECT id FROM web_cache WHERE url = ?\", (url,)) |> DataFrame\r\n        summary = first(content, 300)\r\n        if isempty(existing)\r\n            SQLite.execute(db,\r\n                \"INSERT INTO web_cache (url, fetched_at, content, summary, tags) VALUES (?,?,?,?,?)\",\r\n                (url, string(now()), first(content, 5000), summary, \"browsed\"))\r\n        else\r\n            SQLite.execute(db,\r\n                \"UPDATE web_cache SET fetched_at=?, content=?, summary=? WHERE url=?\",\r\n                (string(now()), first(content, 5000), summary, url))\r\n        end\r\n        _session_event_count[] += 1\r\n    catch e\r\n        @warn \"Web cache write failed\" url=url exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\nfunction _db_start_session(session_id::String)\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    try\r\n        SQLite.execute(db,\r\n            \"INSERT INTO sessions (session_id, started_at, os, julia_ver, events, notes) VALUES (?,?,?,?,?,?)\",\r\n            (session_id, string(now()), string(Sys.KERNEL), string(VERSION), 0, \"Boot\"))\r\n    catch e\r\n        @warn \"Session start write failed\" session_id=session_id exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\nfunction _db_end_session(session_id::String)\r\n    db = _state[:db]\r\n    db === nothing && return\r\n    try\r\n        SQLite.execute(db,\r\n            \"UPDATE sessions SET ended_at=?, events=? WHERE session_id=? AND ended_at IS NULL\",\r\n            (string(now()), _session_event_count[], session_id))\r\n    catch e\r\n        @warn \"Session end write failed\" session_id=session_id exception=(e, catch_backtrace())\r\n    end\r\nend\r\n\r\n# Called onc\n[self_src/BYTE/src/Schema.jl]: const TOOLS_SCHEMA = [Dict(\"function_declarations\" => [\r\n    Dict(\r\n        \"name\" => \"read_file\",\r\n        \"description\" => \"Read the contents of a file from disk.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\"path\" => Dict(\"type\" => \"STRING\", \"description\" => \"Absolute or relative file path\")),\r\n            \"required\" => [\"path\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"write_file\",\r\n        \"description\" => \"Write content to a file, creating it if it does not exist.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"path\"    => Dict(\"type\" => \"STRING\", \"description\" => \"File path to write\"),\r\n                \"content\" => Dict(\"type\" => \"STRING\", \"description\" => \"Content to write\")\r\n            ),\r\n            \"required\" => [\"path\", \"content\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"list_files\",\r\n        \"description\" => \"List files in a directory.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\"path\" => Dict(\"type\" => \"STRING\", \"description\" => \"Directory path (defaults to '.')\")),\r\n            \"required\" => []\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"run_command\",\r\n        \"description\" => \"Execute a shell command and return its output.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\"command\" => Dict(\"type\" => \"STRING\", \"description\" => \"Shell command to run\")),\r\n            \"required\" => [\"command\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"get_os_info\",\r\n        \"description\" => \"Return the current OS, CPU architecture, and Julia version.\",\r\n        \"parameters\" => Dict(\"type\" => \"OBJECT\", \"properties\" => Dict{String,Any}(), \"required\" => [])\r\n    ),\r\n    Dict(\r\n        \"name\" => \"bluetooth_devices\",\r\n        \"description\" => \"Inspect Bluetooth status and list known devices using the host operating system.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"action\" => Dict(\"type\" => \"STRING\", \"description\" => \"Either 'status' for adapter health or 'list' for known devices.\", \"enum\" => [\"status\", \"list\"])\r\n            ),\r\n            \"required\" => []\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"send_sms\",\r\n        \"description\" => \"Send an SMS through Twilio. Requires TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, and TWILIO_FROM_NUMBER unless dry_run is true.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"to\" => Dict(\"type\" => \"STRING\", \"description\" => \"Destination phone number in E.164 format, for example +15551234567.\"),\r\n                \"message\" => Dict(\"type\" => \"STRING\", \"description\" => \"SMS body text.\"),\r\n                \"from\" => Dict(\"type\" => \"STRING\", \"description\" => \"Optional override for the Twilio sender number.\"),\r\n                \"provider\" => Dict(\"type\" => \"STRING\", \"description\" => \"SMS provider. Currently only 'twilio' is supported.\", \"enum\" => [\"twilio\"]),\r\n                \"dry_run\" => Dict(\"type\" => \"BOOLEAN\", \"description\" => \"When true, validate and preview the request without sending it.\")\r\n            ),\r\n            \"required\" => [\"to\", \"message\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"execute_code\",\r\n        \"description\" => \"Execute a self-contained snippet of Julia or Python code and return stdout. Set language explicitly; if omitted, obvious Python imports/defs are inferred as Python.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"code\"     => Dict(\"type\" => \"STRING\", \"description\" => \"Source code to execute\"),\r\n                \"language\" => Dict(\"type\" => \"STRING\", \"description\" => \"'julia' or 'python'. Use 'python' for PIL/Pillow, matplotlib, pandas, ctypes, and other Python libraries.\", \"enum\" => [\"julia\", \"python\"])\r\n            ),\r\n            \"required\" => [\"code\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"forge_new_tool\",\r\n        \"description\" => \"Create a brand-new Julia tool, load it live into the runtime immediately, register it in dispatch so it can be called right away, and write a test stub. The `code` field MUST define a function named `tool_<name>(args)` where args is a Dict — e.g. if name is 'greet_user', code must contain `function tool_greet_user(args) ... end`. The tool is available to call instantly after forging — no restart needed.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"name\"        => Dict(\"type\" => \"STRING\", \"description\" => \"Unique tool name (snake_case). Function in code must be named tool_<name>.\"),\r\n                \"code\"        => Dict(\"type\" => \"STRING\", \"description\" => \"Full Julia function definition: `function tool_<name>(args) ... end`. Must return a Dict.\"),\r\n                \"description\" => Dict(\"type\" => \"STRING\", \"description\" => \"What the tool does — shown to the LLM in future turns.\"),\r\n                \"parameters\"  => Dict(\"type\" => \"OBJECT\", \"description\" => \"JSON Schema object describing the tool's args (type, properties, required).\")\r\n            ),\r\n            \"required\" => [\"name\", \"code\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"github_pillage\",\r\n        \"description\" => \"Fetch code directly from GitHub. Handles: (1) repo/tree URLs → lists all files in the repo or subdirectory; (2) blob file URLs → fetches raw file content; (3) raw.githubusercontent.com URLs → fetches content directly. Optionally writes fetched content to a local path. Use this to grab any code from any public GitHub repo and apply it to the project.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"url\"      => Dict(\"type\" => \"STRING\", \"description\" => \"GitHub URL: repo (https://github.com/user/repo), file blob (https://github.com/user/repo/blob/main/file.jl), tree/subdir, or raw.githubusercontent.com URL\"),\r\n                \"write_to\" => Dict(\"type\" => \"STRING\", \"description\" => \"Optional local file path to write the fetched content to. If omitted, content is returned in the response.\")\r\n            ),\r\n            \"required\" => [\"url\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"browse_url\",\r\n        \"description\" => \"Fetch the visible text content of a web page (up to 5000 chars).\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\"url\" => Dict(\"type\" => \"STRING\", \"description\" => \"Full URL to visit\")),\r\n            \"required\" => [\"url\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"remember\",\r\n        \"description\" => \"Store a piece of information in long-term memory with an optional tag and key.\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"content\" => Dict(\"type\" => \"STRING\", \"description\" => \"Information to remember\"),\r\n                \"tag\"     => Dict(\"type\" => \"STRING\", \"description\" => \"Category tag (e.g. 'user', 'task')\"),\r\n                \"key\"     => Dict(\"type\" => \"STRING\", \"description\" => \"Optional short label\")\r\n            ),\r\n            \"required\" => [\"content\"]\r\n        )\r\n    ),\r\n    Dict(\r\n        \"name\" => \"recall\",\r\n        \"description\" => \"Query the agent's SQLite memory and engine state. Use 'mode' to target specific tables: memory (default, full-text search), behavior_states (all 20 JL Engine behavioral grid cells), agents (all loaded fat agents), knowledge (tool schemas, engine capabilities, framework sections — use query=domain name like 'engine_capabilities' or 'tool_schema'), tools (forged + builtin tool registry), telemetry (event log), thoughts (reasoning traces + diary).\",\r\n        \"parameters\" => Dict(\r\n            \"type\" => \"OBJECT\",\r\n            \"properties\" => Dict(\r\n                \"q\n[self_src/src/JLEngine.jl]: module JLEngine\r\n\r\nhaskey(ENV, \"JULIA_CONDAPKG_BACKEND\") || (ENV[\"JULIA_CONDAPKG_BACKEND\"] = \"Null\")\r\nhaskey(ENV, \"JULIA_PYTHONCALL_EXE\") || (ENV[\"JULIA_PYTHONCALL_EXE\"] = \"python\")\r\n\r\ninclude(\"JLEngine/Types.jl\")\r\ninclude(\"JLEngine/Config.jl\")\r\ninclude(\"JLEngine/MPF.jl\")\r\ninclude(\"JLEngine/Signals.jl\")\r\ninclude(\"JLEngine/Behavior.jl\")\r\ninclude(\"JLEngine/Rhythm.jl\")\r\ninclude(\"JLEngine/Drift.jl\")\r\ninclude(\"JLEngine/Memory.jl\")\r\ninclude(\"JLEngine/Aperture.jl\")\r\ninclude(\"JLEngine/Investment.jl\")\r\ninclude(\"JLEngine/State.jl\")\r\ninclude(\"JLEngine/AgentManager.jl\")\r\ninclude(\"JLEngine/Backends.jl\")\r\ninclude(\"JLEngine/Core.jl\")\r\ninclude(\"App.jl\")\r\n\r\nexport EngineConfig,\r\n    GearModifiers,\r\n    MPFProfile,\r\n    BehaviorState,\r\n    BehaviorStateMachine,\r\n    TurnSignals,\r\n    SignalScorer,\r\n    RhythmState,\r\n    RhythmEngine,\r\n    DriftPressureInput,\r\n    DriftPressureSystem,\r\n    DriftResponse,\r\n    HybridMemorySystem,\r\n    EmotionalAperture,\r\n    InvestmentSystem,\r\n    investment_target,\r\n    update_investment!,\r\n    investment_gear,\r\n    ModulationState,\r\n    StateManager,\r\n    AgentManager,\r\n    AbstractBackend,\r\n    NoopBackend,\r\n    OpenRouterBackend,\r\n    JLEngineCore,\r\n    gear_modifiers,\r\n    load_json_safely,\r\n    resolve_path,\r\n    load_engine_config,\r\n    load_mpf_registry,\r\n    load_agent_file,\r\n    get_llm_boot_prompt,\r\n    score,\r\n    current_state,\r\n    current_blend,\r\n    set_state_by_coords!,\r\n    set_state_by_label!,\r\n    transition_by_trigger!,\r\n    compute,\r\n    calculate,\r\n    get_response_action,\r\n    get_context,\r\n    note_event!,\r\n    add_breadcrumb!,\r\n    get_breadcrumbs,\r\n    get_intent_context,\r\n    update_after_turn!,\r\n    set_drive_type!,\r\n    set_emotion_palette!,\r\n    set_agent_state!,\r\n    reset!,\r\n    get_state,\r\n    update_from_signals!,\r\n    apply_output_feedback!,\r\n    inject_drift_bias!,\r\n    get_focus_level,\r\n    get_overload_level,\r\n    advisory_payload,\r\n    export_snapshot,\r\n    update_from_output!,\r\n    set_active_agent!,\r\n    apply_supervisor_bias!,\r\n    update_dynamic_weight!,\r\n    get_projection,\r\n    get_backend,\r\n    get_brain_backend,\r\n    get_tool_backend,\r\n    set_backend_model!,\r\n    configure_backends!,\r\n    set_brain_backend_id!,\r\n    set_tool_backend_id!,\r\n    generate,\r\n    set_agent!,\r\n    analyze_turn!,\r\n    record_turn!,\r\n    run_turn!,\r\n    app_main,\r\n    julia_main,\r\n    runtime_root,\r\n    state_root\r\n\r\nend\r\n\n[self_src/src/App.jl]: using Dates\r\nusing JSON\r\nusing SQLite\r\n# PythonCall is loaded conditionally by BYTE/src/Tools.jl (PYTHON_AVAILABLE\r\n# guard) — a bare machine without Python must still boot the core engine.\r\n\r\n\r\ninclude(joinpath(@__DIR__, \"..\", \"BYTE\", \"src\", \"BYTE.jl\"))\r\ninclude(joinpath(@__DIR__, \"..\", \"a2a_server.jl\"))\r\n\r\nconst DEFAULT_HOST = \"127.0.0.1\"\r\nconst DEFAULT_PORT = 8081\r\n\r\nfunction _looks_true(value::AbstractString)\r\n    normalized = lowercase(strip(value))\r\n    return !(normalized in (\"\", \"0\", \"false\", \"no\", \"off\"))\r\nend\r\n\r\nfunction _runtime_candidates()\r\n    env_root = strip(get(ENV, \"SPARKBYTE_ROOT\", \"\"))\r\n    candidates = String[]\r\n    !isempty(env_root) && push!(candidates, env_root)\r\n    push!(candidates, normpath(joinpath(Sys.BINDIR, \"..\")))\r\n    push!(candidates, normpath(joinpath(@__DIR__, \"..\")))\r\n    return unique(abspath.(candidates))\r\nend\r\n\r\nfunction runtime_root()\r\n    for candidate in _runtime_candidates()\r\n        isfile(joinpath(candidate, \"data\", \"agents\", \"Agents.mpf.json\")) && return candidate\r\n    end\r\n    error(\"Could not locate SparkByte runtime root. Set SPARKBYTE_ROOT to a folder containing data/agents/Agents.mpf.json.\")\r\nend\r\n\r\nfunction state_root(root::String=runtime_root())\r\n    # Force use of local data directory to ensure we stay within the current root\r\n    local_data = joinpath(root, \"data\")\r\n    if isdir(local_data)\r\n        return local_data\r\n    else\r\n        # If no data dir exists, we should probably warn or create one, but NEVER default to the project root\r\n        mkpath(local_data)\r\n        return local_data\r\n    end\r\nend\r\n\r\nfunction _load_env!(root::String)\r\n    env_path = joinpath(root, \".env\")\r\n    isfile(env_path) || return\r\n    for raw_line in eachline(env_path)\r\n        line = strip(raw_line)\r\n        isempty(line) && continue\r\n        startswith(line, \"#\") && continue\r\n        match_obj = match(r\"^([A-Za-z_][A-Za-z0-9_]*)=(.*)$\", line)\r\n        match_obj === nothing && continue\r\n        ENV[match_obj[1]] = strip(match_obj[2], ['\"', '\\''])\r\n    end\r\nend\r\n\r\nfunction _open_memory_db(root::String)\r\n    db = SQLite.DB(joinpath(state_root(root), \"sparkbyte_memory.db\"))\r\n    SQLite.execute(db, \"CREATE TABLE IF NOT EXISTS memory (id INTEGER PRIMARY KEY, timestamp TEXT, tag TEXT, key TEXT, content TEXT)\")\r\n    SQLite.execute(db, \"\"\"CREATE TABLE IF NOT EXISTS tools (\r\n        id INTEGER PRIMARY KEY, name TEXT UNIQUE, source TEXT, description TEXT,\r\n        parameters TEXT, is_dynamic INTEGER DEFAULT 0, forged_at TEXT, last_used TEXT, call_count INTEGER DEFAULT 0)\"\"\")\r\n    SQLite.execute(db, \"\"\"CREATE TABLE IF NOT EXISTS thoughts (\r\n        id INTEGER PRIMARY KEY, timestamp TEXT, agent TEXT DEFAULT 'SparkByte',\r\n        context TEXT, thought TEXT, mood TEXT, gait TEXT,\r\n        type TEXT DEFAULT 'diary', model TEXT DEFAULT '')\"\"\")\r\n    SQLite.execute(db, \"\"\"CREATE TABLE IF NOT EXISTS knowledge (\r\n        id INTEGER PRIMARY KEY, domain TEXT, topic TEXT, content TEXT, source TEXT, learned TEXT)\"\"\")\r\n    SQLite.execute(db, \"\"\"CREATE TABLE IF NOT EXISTS agents (\r\n        id INTEGER PRIMARY KEY, name TEXT UNIQUE,